.nodo-card {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: var(--spacing3);
  padding: var(--spacing4);
  border-radius: var(--radius-medium);
  background: var(--surface-container-low);
  color: var(--on-surface);
  text-decoration: none;
  isolation: isolate;
  transition: box-shadow var(--transition-fast), transform var(--transition-fast);
}
.nodo-card--elevated { box-shadow: var(--elevation-1); }
.nodo-card--filled   { background: var(--surface-container); box-shadow: none; }
.nodo-card--outlined { background: var(--surface); box-shadow: none; border: 1px solid var(--outline-high); }

.nodo-card__state-layer {
  position: absolute; inset: 0; z-index: 0;
  border-radius: inherit;
  background: var(--on-surface);
  opacity: 0;
  transition: opacity var(--transition-fast);
  pointer-events: none;
}
.nodo-card > :not(.nodo-card__state-layer) { position: relative; z-index: 1; }

.nodo-card:hover .nodo-card__state-layer { opacity: 0.08; }
.nodo-card:hover.nodo-card--elevated { box-shadow: var(--elevation-2); }
.nodo-card:focus-visible {
  outline: 2px solid var(--nodo-primary-light);
  outline-offset: 2px;
}
.nodo-card:focus-visible .nodo-card__state-layer { opacity: 0.10; }
.nodo-card:active .nodo-card__state-layer { opacity: 0.10; }
.nodo-card:active { transform: scale(0.995); box-shadow: var(--elevation-1); }

.nodo-card[aria-selected="true"] {
  background: var(--primary-container);
  border: 1.5px solid var(--primary);
}
.nodo-card[aria-disabled="true"] {
  pointer-events: none;
  box-shadow: none;
}
.nodo-card[aria-disabled="true"] > :not(.nodo-card__state-layer) { opacity: 0.38; }

.nodo-card__media {
  width: 100%;
  aspect-ratio: 16 / 9;
  object-fit: cover;
  border-radius: var(--radius-small);
  background: var(--surface-container);
}
.nodo-card__content { display: flex; flex-direction: column; gap: var(--spacing1); }
.nodo-card__headline {
  font-size: 16px; line-height: 24px; font-weight: 600;
  color: var(--on-surface);
  display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden;
}
.nodo-card__subhead {
  font-size: 12px; line-height: 16px; font-weight: 600;
  color: var(--on-surface-low);
}
.nodo-card__supporting {
  font-size: 14px; line-height: 20px; font-weight: 400;
  color: var(--on-surface-variant);
  display: -webkit-box; -webkit-line-clamp: 3; -webkit-box-orient: vertical; overflow: hidden;
}
.nodo-card__actions {
  display: flex; justify-content: flex-end; gap: var(--spacing2);
  padding-block: var(--spacing2);
}

@media (prefers-reduced-motion: reduce) {
  .nodo-card { transition: opacity 100ms linear; }
  .nodo-card:active { transform: none; }
}
